import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    iterator = iter(data)
    H = int(next(iterator))
    W = int(next(iterator))
    M = int(next(iterator))

    row_counts = {}
    col_counts = {}
    targets = set()

    for _ in range(M):
        h = int(next(iterator))
        w = int(next(iterator))
        row_counts[h] = row_counts.get(h, 0) + 1
        col_counts[w] = col_counts.get(w, 0) + 1
        targets.add((h, w))

    max_destroyed = 0

    # Check intersections for rows that have targets
    for r in row_counts:
        for c in col_counts:
            count = row_counts[r] + col_counts[c]
            if (r, c) in targets:
                count -= 1
            if count > max_destroyed:
                max_destroyed = count

    print(max_destroyed)

if __name__ == "__main__":
    solve()
